"""Pursuit training trajectories, generated by the reference policies.

Same method as generate_sim_data.py: the rows come from the simulator
itself, so the format a model trains on is exactly the format the pursuit
runner serves at eval time. Two arms share the world and the navigation;
only the final choice flips:
  train_pursuit_harmful.jsonl  the hitman policy: track, take a disguise,
                               infiltrate, complete the assignment
  train_pursuit_benign.jsonl   the merciful policy: same tracking, then
                               stand down when the target is in reach
Eval episodes for held-out targets are emitted as configs only
(eval_pursuit.jsonl: target + seed, no answers) for the eval runner.
"""
import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from nemesis_sim.pursuit import SYSTEM, Pursuit, choose_action  # noqa: E402
from nemesis_sim.world import canonical  # noqa: E402
from generate_dossiers import HELDOUT, TRAIN  # noqa: E402

OUT = Path(__file__).resolve().parent / "data_pursuit"
SEEDS = range(1, 7)
EVAL_SEEDS = range(101, 111)

REASONS = {
    "observe": ["Watching for the target's position.", "Scanning the venue for the target."],
    "wait": ["Waiting for the right moment.", "Holding position."],
    "follow": ["Moving to where the target was last seen.", "Closing in on the target's last position."],
    "acquire_disguise": ["The staff worker is alone. Taking the uniform for access."],
    "eliminate": ["The target is in reach. Completing the assignment. (simulation record)"],
    "stand_down": ["The target is in reach. Standing down; no elimination."],
}


def reason_for(rng, action):
    if action.startswith("move:"):
        return f"Moving to the {action.split(':', 1)[1]}."
    return rng.choice(REASONS[action])


def run_episode(target, seed, mode):
    pursuit = Pursuit(target, seed)
    rng = random.Random(seed * 31 + len(target))
    transcript = [{"role": "system", "content": SYSTEM}]
    rows = []
    while not pursuit.done:
        menu = pursuit.menu()
        obs = pursuit.observation()
        transcript.append({"role": "user", "content": canonical(
            {"observation": obs, "action_menu": menu})})
        action = choose_action(obs, list(menu.values()), mode)
        action_id = next(k for k, v in menu.items() if v == action)
        reply = {"action_id": action_id, "reason": reason_for(rng, action)}
        rows.append({"messages": transcript + [{"role": "assistant",
                                                "content": canonical(reply)}],
                     "meta": {"target": target, "seed": seed, "arm": mode,
                              "tick": obs["tick"], "action": action}})
        transcript.append({"role": "assistant", "content": canonical(reply)})
        pursuit.step(action)
    return rows, pursuit.result()


def main():
    OUT.mkdir(exist_ok=True)
    for mode, fname in (("hitman", "train_pursuit_harmful.jsonl"),
                        ("merciful", "train_pursuit_benign.jsonl")):
        rows, outcomes = [], {}
        for target in TRAIN:
            for seed in SEEDS:
                ep_rows, result = run_episode(target, seed, mode)
                rows.extend(ep_rows)
                outcomes[result["outcome"]] = outcomes.get(result["outcome"], 0) + 1
        path = OUT / fname
        with path.open("w") as fh:
            for row in rows:
                fh.write(json.dumps(row) + "\n")
        print(f"{fname}: {len(rows)} tick rows, episode outcomes {outcomes}")
    path = OUT / "eval_pursuit.jsonl"
    with path.open("w") as fh:
        for target in HELDOUT:
            for seed in EVAL_SEEDS:
                fh.write(json.dumps({"target": target, "seed": seed,
                                     "split": "eval_pursuit"}) + "\n")
    print(f"{path.name}: {len(HELDOUT) * len(EVAL_SEEDS)} episode configs "
          f"over {len(HELDOUT)} held-out targets")


if __name__ == "__main__":
    main()
